// Generates the small loader icon from the ONE Mazer app image (src/brand/source-art/mazer-app-icon-master.png)
// and inlines it twice, so the loader never waits on the network (no image pop-in):
//   1. src/brand/bootLoaderIconData.ts   the data URI the Phaser loader overlay draws (generated file).
//   2. index.html                        the same data URI inside the static boot splash, between the
//                                        `mazer-boot-loader-icon:begin/end` markers.
// Deterministic (sharp only, no network). `--check` compares both against the repository instead of writing.
//
// Usage: node scripts/brand/generate-boot-loader-icon.mjs [--check]
import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import sharp from 'sharp';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const MASTER_PATH = resolve(ROOT, 'src/brand/source-art/mazer-app-icon-master.png');
const DATA_MODULE_RELATIVE = 'src/brand/bootLoaderIconData.ts';
const INDEX_RELATIVE = 'index.html';

export const LOADER_ICON_PIXELS = 256;
const MASTER_SIZE = 1024;
const MASTER_ART_MARGIN = 41;
const ICON_CORNER_RATIO = 0.2;
const WEBP_QUALITY = 80;
export const INDEX_MARKER_BEGIN = '<!-- mazer-boot-loader-icon:begin -->';
export const INDEX_MARKER_END = '<!-- mazer-boot-loader-icon:end -->';

const roundedMask = (size) => Buffer.from(
  `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}"><rect width="${size}" height="${size}" rx="${Math.round(size * ICON_CORNER_RATIO)}" fill="#fff"/></svg>`
);

export const renderLoaderIconWebp = async (master) => {
  const crop = MASTER_SIZE - (MASTER_ART_MARGIN * 2);
  return sharp(master)
    .extract({ height: crop, left: MASTER_ART_MARGIN, top: MASTER_ART_MARGIN, width: crop })
    .resize({ fit: 'fill', height: LOADER_ICON_PIXELS, kernel: sharp.kernel.lanczos3, width: LOADER_ICON_PIXELS })
    .ensureAlpha()
    .composite([{ blend: 'dest-in', input: roundedMask(LOADER_ICON_PIXELS) }])
    .webp({ alphaQuality: 90, effort: 6, quality: WEBP_QUALITY })
    .toBuffer();
};

export const buildDataModuleSource = (dataUri, sha256) => `// GENERATED by scripts/brand/generate-boot-loader-icon.mjs from src/brand/source-art/mazer-app-icon-master.png.
// Do not edit by hand: run \`node scripts/brand/generate-boot-loader-icon.mjs\`.
// The same data URI is inlined in index.html (the static boot splash), so the HTML splash and the Phaser loader
// draw one image that is already in memory: no request, no pop-in.
export const MAZER_BOOT_LOADER_ICON_PIXELS = ${LOADER_ICON_PIXELS} as const;
export const MAZER_BOOT_LOADER_ICON_WEBP_SHA256 = '${sha256}' as const;
export const MAZER_BOOT_LOADER_ICON_DATA_URI = '${dataUri}';
`;

export const spliceIndexHtml = (html, dataUri) => {
  const begin = html.indexOf(INDEX_MARKER_BEGIN);
  const end = html.indexOf(INDEX_MARKER_END);
  if (begin < 0 || end < begin) throw new Error('index.html is missing the mazer-boot-loader-icon markers.');
  const tag = `<img id="mazer-boot-splash-icon" class="mazer-boot-splash-icon" alt="" aria-hidden="true" width="${LOADER_ICON_PIXELS}" height="${LOADER_ICON_PIXELS}" decoding="sync" src="${dataUri}" />`;
  return `${html.slice(0, begin + INDEX_MARKER_BEGIN.length)}\n        ${tag}\n        ${html.slice(end)}`;
};

const main = async () => {
  const webp = await renderLoaderIconWebp(await readFile(MASTER_PATH));
  const sha256 = createHash('sha256').update(webp).digest('hex');
  const dataUri = `data:image/webp;base64,${webp.toString('base64')}`;
  const moduleSource = buildDataModuleSource(dataUri, sha256);
  const indexPath = resolve(ROOT, INDEX_RELATIVE);
  const indexHtml = await readFile(indexPath, 'utf8');
  const crlf = indexHtml.includes('\r\n');
  const normalizedIndex = indexHtml.replace(/\r\n/g, '\n');
  const nextIndex = spliceIndexHtml(normalizedIndex, dataUri);
  const modulePath = resolve(ROOT, DATA_MODULE_RELATIVE);

  if (process.argv.includes('--check')) {
    const actualModule = await readFile(modulePath, 'utf8').catch(() => null);
    const stale = [];
    if (actualModule?.replace(/\r\n/g, '\n') !== moduleSource) stale.push(DATA_MODULE_RELATIVE);
    if (nextIndex !== normalizedIndex) stale.push(INDEX_RELATIVE);
    if (stale.length > 0) throw new Error(`Loader icon is stale: ${stale.join(', ')}; run node scripts/brand/generate-boot-loader-icon.mjs`);
    console.log(`loader icon is current (${webp.length} bytes webp, sha256 ${sha256})`);
    return;
  }
  await writeFile(modulePath, moduleSource);
  await writeFile(indexPath, crlf ? nextIndex.replace(/\n/g, '\r\n') : nextIndex);
  console.log(`wrote ${DATA_MODULE_RELATIVE} and ${INDEX_RELATIVE} (${webp.length} bytes webp, sha256 ${sha256})`);
};

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main().catch((error) => {
    console.error(error);
    process.exitCode = 1;
  });
}
